INSERT INTO public.report_card VALUES (44, '2024-07-17 16:34:54.532447+02', '2025-06-30 12:23:46.971528+02', 'Isolated - New or Changed Methods', 'Changes not tested in Build compared to Baseline Build.', 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"b0fa82b0-2234-4e10-bdde-fde786222085","display-name":"Build","required":true},"baseline":{"type":"text","name":"baseline","id":"f03b9234-08fc-4c9a-b51a-53211c8ad752","display-name":"Baseline","required":true},"env":{"type":"text","name":"env","id":"c3370bcf-c868-4865-8cc5-56e72a2260f5","display-name":"Env"},"branch":{"type":"text","name":"branch","id":"de6ad949-a030-4a7f-9876-86cb3cd20e31","display-name":"Branch"},"test_tag":{"type":"text","name":"test_tag","id":"d2c0b972-47f4-449f-a063-3b69859788e0","display-name":"Test Tag"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT * \r\n        FROM raw_data.get_build_coverage_v2(\r\n        input_build_id => {{build}},\r\n        input_aggregated_coverage => false,\r\n        input_materialized => true,\r\n        input_baseline_build_id => {{baseline}}\r\n        [[, input_test_tag => {{test_tag}} ]]\r\n        [[, input_env_id => {{env}} ]]\r\n        [[, input_branch => {{branch}} ]]\r\n    )\r\n)\r\nSELECT\r\n    ''Tested'' AS metric,\r\n    isolated_tested_changes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Not Tested'' as metric,\r\n    (total_changes - isolated_tested_changes) AS value\r\nFROM BuildCoverage"}}', '{"table.columns":[{"name":"value","fieldRef":["field","value",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"metric","fieldRef":["field","metric",{"base-type":"type/Text"}],"enabled":true}],"table.column_formatting":[{"columns":["__covered_probes"],"type":"single","operator":"=","value":0,"color":"#EF8C8C","highlight_row":true},{"max_value":1,"color":"#509EE3","columns":["__probes_coverage_ratio"],"value":"","type":"range","colors":["#ED6E6E","#F9CF48","#84BB4C"],"highlight_row":false,"min_value":0,"min_type":"custom","operator":"=","max_type":"custom"}],"table.pivot_column":"not_tested_risks","pie.colors":{"Tested":"#227FD2","Untested":"#ED8535","Fully Tested":"#227FD2","Partially Tested":"#87BCEC","Not Tested":"#F2A86F"},"pie.slice_threshold":1,"column_settings":{"[\"name\",\"__name\"]":{"column_title":"Method"},"[\"name\",\"__classname\"]":{"column_title":"Class"},"[\"name\",\"__probes_count\"]":{"column_title":"Probes"},"[\"name\",\"__signature\"]":{"column_title":"Signature"},"[\"name\",\"__return_type\"]":{"column_title":"Return Type"},"[\"name\",\"__params\"]":{"column_title":"Parameters"},"[\"name\",\"__build_ids_coverage_source\"]":{"column_title":"Tested in other builds"},"[\"name\",\"__probes_coverage_ratio\"]":{"column_title":"Coverage %","number_style":"percent"},"[\"name\",\"__risk_type\"]":{"column_title":"Change Type"},"[\"name\",\"__covered_probes\"]":{"column_title":"Covered probes"}}}', 1, 2, NULL, 'native', true, 5, NULL, NULL, false, NULL, NULL, '[{"display_name":"metric","field_ref":["field","metric",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"metric","semantic_type":null,"fingerprint":{"global":{"distinct-count":2,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":8.0}}}},{"display_name":"value","field_ref":["field","value",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"value","semantic_type":null,"fingerprint":{"global":{"distinct-count":2,"nil%":0.0},"type":{"type/Number":{"min":11.0,"q1":11.0,"q3":25.0,"max":25.0,"sd":9.899494936611665,"avg":18.0}}}}]', NULL, 'F4EOxVrLIOQZ_HgEjr_oD', '[{"id":"b0fa82b0-2234-4e10-bdde-fde786222085","type":"category","target":["variable",["template-tag","build"]],"name":"Build","slug":"build","required":true},{"id":"f03b9234-08fc-4c9a-b51a-53211c8ad752","type":"category","target":["variable",["template-tag","baseline"]],"name":"Baseline","slug":"baseline","required":true},{"id":"c3370bcf-c868-4865-8cc5-56e72a2260f5","type":"category","target":["variable",["template-tag","env"]],"name":"Env","slug":"env"},{"id":"de6ad949-a030-4a7f-9876-86cb3cd20e31","type":"category","target":["variable",["template-tag","branch"]],"name":"Branch","slug":"branch"},{"id":"d2c0b972-47f4-449f-a063-3b69859788e0","type":"category","target":["variable",["template-tag","test_tag"]],"name":"Test Tag","slug":"test_tag"}]', '[]', true, 'v0.48.6 (b8818f9)', 'question', NULL, NULL, '2025-03-28 13:42:42.10153+01', 217, true, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (48, '2024-07-24 15:50:46.271248+02', '2025-06-30 12:23:48.925324+02', 'Isolated - Package Coverage', NULL, 'table', '{"type":"native","database":2,"native":{"query":"WITH\r\nMethodsCoverage AS (\r\n\tSELECT\r\n\t\tREVERSE(\r\n\t\t\tSUBSTRING(\r\n\t\t\t\tREVERSE(classname) FROM POSITION(''/'' IN REVERSE(classname)) + 1)) AS package_name,\r\n\t\t*\r\n\tFROM raw_data.get_materialized_methods_coverage(\r\n\t    input_group_id => split_part({{build}}, '':'', 1),\r\n\t    input_app_id => split_part({{build}}, '':'', 2),\r\n\t\tinput_build_id => {{build}},\r\n\t\tinput_aggregated_coverage => false\r\n\t\t[[, input_env_id => {{env_id}} ]]\r\n        [[, input_test_tag => {{tags}} ]]\r\n\t)\r\n)\r\nSELECT\r\n\tpackage_name,\r\n\tSUM(probes_count) as probes_count,\r\n\tSUM(isolated_covered_probes) as covered_probes,\r\n\tSUM(isolated_missed_probes) as missed_probes,\r\n\tCAST(SUM(isolated_covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio\r\nFROM MethodsCoverage\r\nGROUP BY package_name\r\nORDER BY\r\n    missed_probes DESC;","template-tags":{"build":{"type":"text","name":"build","id":"089b65d5-7b8a-4cb6-96cd-07e91a1d233e","display-name":"Build"},"env_id":{"type":"text","name":"env_id","id":"eb932bf3-49f5-4f8c-b3dc-a7aab77d96cc","display-name":"Env ID"},"tags":{"type":"text","name":"tags","id":"a18a6d2d-1af5-4857-99c5-d5559eef57f7","display-name":"Tags"}}}}', '{"graph.show_goal":false,"graph.show_values":false,"scatter.bubble":"probes_count","table.columns":[{"name":"package_name","fieldRef":["field","package_name",{"base-type":"type/Text"}],"enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"covered_probes","fieldRef":["field","covered_probes",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"probes_coverage_ratio","fieldRef":["field","probes_coverage_ratio",{"base-type":"type/Float"}],"enabled":true},{"name":"misse