INSERT INTO public.report_card VALUES (124, '2025-03-19 16:44:22.155968+01', '2025-07-16 08:01:24.015434+02', 'Aggregate - Methods - Duplicate', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"a36a7214-4dbc-4a80-9cf8-02d6749cf8a3","display-name":"Build"},"baseline":{"type":"text","name":"baseline","id":"4d709d38-8c76-4ca2-8f54-5250429ecbeb","display-name":"Baseline"},"test_tag":{"type":"text","name":"test_tag","id":"5da36f29-c1f8-48bf-9775-43bab92b4cd7","display-name":"Test Tag"},"env":{"type":"text","name":"env","id":"cfab6ab2-58bf-45cf-8e12-14f967cd27f6","display-name":"Env"},"branch":{"type":"text","name":"branch","id":"f4301428-2682-4c42-9f6f-c86b219747a6","display-name":"Branch"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT * \r\n        FROM raw_data.get_materialized_build_coverage(\r\n        input_group_id => split_part({{build}}, '':'', 1),\r\n        input_app_id => split_part({{build}}, '':'', 2),\r\n        input_build_id => {{build}},\r\n        input_aggregated_coverage => true\r\n        [[, input_baseline_build_id => {{baseline}}]]\r\n        [[, input_test_tag => {{test_tag}} ]]\r\n        [[, input_env_id => {{env}} ]]\r\n        [[, input_branch => {{branch}} ]]\r\n    )\r\n)\r\nSELECT\r\n    ''Fully Tested'' AS metric,\r\n    aggregated_tested_changes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Partially Tested'' as metric,\r\n    aggregated_partially_tested_changes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Not Tested'' as metric,\r\n    (total_changes - aggregated_tested_changes - aggregated_partially_tested_changes) AS value\r\nFROM BuildCoverage"}}', '{"graph.show_goal":false,"pie.slice_threshold":1,"pie.percent_visibility":"legend","pie.dimension":"metric","graph.series_order_dimension":null,"progress.goal":100,"pie.colors":{"Tested to some extent":"#227FD2","Untested":"#ED8535","No coverage":"#F2A86F","100% Tested":"#227FD2","Test