INSERT INTO public.report_card VALUES (134, '2025-03-28 13:05:31.269805+01', '2025-06-30 13:00:22.855182+02', 'New or Changed Methods - Probes', 'Changes not tested in Build compared to Baseline Build.', 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"b0fa82b0-2234-4e10-bdde-fde786222085","display-name":"Build","required":true},"branch":{"type":"text","name":"branch","id":"06790b5d-5d2c-4abe-9c40-b0aae94636ff","display-name":"Branch"},"baseline":{"type":"text","name":"baseline","id":"10a4e87d-9446-4021-9de0-a1c5a040103d","display-name":"Baseline","required":true},"test_tag":{"type":"text","name":"test_tag","id":"803271f6-0767-489b-9bb6-cd103d0b58ef","display-name":"Test Tag"},"env":{"type":"text","name":"env","id":"377b779c-d016-4ec6-8520-8d1ca75a2a44","display-name":"Env"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT * \r\n    FROM metrics.get_builds_with_coverage(\r\n        input_build_id => {{build}}\r\n        [[, input_baseline_build_id => {{baseline}}]]\r\n        [[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n        [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n        [[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\r\n    )\r\n)\r\nSELECT\r\n    ''Isolated Coverage'' AS metric,\r\n    isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Aggregated Coverage'' AS metric,\r\n    aggregated_covered_probes - isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Gaps'' as metric,\r\n    total_probes - aggregated_covered_probes AS value\r\nFROM BuildCoverage\r\n"}}', '{"table.columns":[{"name":"metric","fieldRef":["field","metric",{"base-type":"type/Text"}],"enabled":true},{"name":"value","fieldRef":["field","value",{"base-type":"type/Integer"}],"enabled":true}],"table.column_formatting":[{"columns":["__covered_probes"],"type":"single","operator":"=","value":0,"color":"#EF8C8