INSERT INTO public.report_card VALUES (49, '2024-07-24 17:41:20.028277+02', '2025-06-30 12:23:38.394564+02', 'Isolated - Classes Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"28c8e3af-50db-4e01-84ba-2ebd1ea897a2","display-name":"Build"},"env_id":{"type":"text","name":"env_id","id":"5f26ffad-3469-42a0-8539-920ea7ef2d25","display-name":"Env ID"},"tags":{"type":"text","name":"tags","id":"aba6b75d-a5fc-430d-8903-1e9ac57ee6f1","display-name":"Tags"},"package":{"type":"text","name":"package","id":"5d5dffe4-856b-4254-bc9d-0b0d5217bd0c","display-name":"Package"}},"query":"WITH\r\nMethodsCoverage AS (\r\n\tSELECT\r\n\t\tREVERSE(\r\n\t\t\tSUBSTRING(\r\n\t\t\t\tREVERSE(classname) FROM POSITION(''/'' IN REVERSE(classname)) + 1)) AS package_name,\r\n\t\t*\r\n\tFROM raw_data.get_materialized_methods_coverage(\r\n\t    input_group_id => split_part({{build}}, '':'', 1),\r\n\t    input_app_id => split_part({{build}}, '':'', 2),\r\n\t\tinput_build_id => {{build}},\r\n\t\tinput_aggregated_coverage => false,\r\n\t\tinput_package_name_pattern => ''%''||{{package}}||''%''\r\n\t\t[[, input_env_id => {{env_id}} ]]\r\n        [[, input_test_tag => {{tags}} ]]\r\n\t)\r\n)\r\nSELECT\r\n    package_name,\r\n\tclassname,\r\n\tSUM(probes_count) as probes_count,\r\n\tSUM(isolated_covered_probes) as covered_probes,\r\n\tSUM(isolated_missed_probes) as missed_probes,\r\n\tCAST(SUM(isolated_covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio\r\nFROM MethodsCoverage\r\nGROUP BY package_name, classname\r\nORDER BY\r\n    missed_probes DESC;"}}', '{"graph.show_goal":false,"graph.show_values":false,"scatter.bubble":"probes_count","table.columns":[{"name":"package_name","fieldRef":["field","package_name",{"base-type":"type/Text"}],"enabled":true},{"name":"classname","fieldRef":["field","classname",{"base-type":"type/Text"}],"enabled":true},{"name":"probes_count","fieldRef":["field","probes_c