INSERT INTO public.report_card VALUES (109, '2025-03-19 16:44:22.155968+01', '2025-07-16 08:02:12.303213+02', 'Time will be saved - Duplicate', NULL, 'scalar', '{"type":"native","database":2,"native":{"query":"WITH \r\n    RecommendedTests AS (\r\n\t\tSELECT \r\n\t\t\ttd.avg_duration AS time_saved\t\t\r\n\t\tFROM raw_data.get_recommended_tests_v4(\r\n\t\t\tinput_target_build_id => {{build}},\r\n\t\t\tinput_tests_to_skip => true\r\n\t\t\t[[, input_baseline_build_id => {{baseline}}]]\r\n\t\t\t[[, input_test_tag => {{test_tag}}]]\r\n\t\t\t[[, input_branch => {{branch}}]]\r\n\t\t\t[[, input_env_id => {{env}}]]\r\n\t\t) AS skips\r\n\t\tJOIN raw_data.view_test_definitions td ON td.test_definition_id = skips.test_definition_id\r\n\t)\r\nSELECT \r\n\tCOALESCE(raw_data.format_duration_rounded(SUM(time_saved)::INT), ''0ms'') AS duration\r\nFROM RecommendedTests;","template-tags":{"build":{"type":"text","name":"build","id":"affebf1f-7bab-4b3d-a023-d46693f7896a","display-name":"Build"},"baseline":{"type":"text","name":"baseline","id":"7a812232-778f-457e-9570-9dbabe1b6795","display-name":"Baseline","required":false},"branch":{"type":"text","name":"branch","id":"bc3337f2-c020-4179-887a-91869546f017","display-name":"Branch"},"env":{"type":"text","name":"env","id":"3e43c992-7f1b-4b39-a6ed-b756b8ca026c","display-name":"Env"},"test_tag":{"type":"text","name":"test_tag","id":"ced80ceb-ee7d-45aa-824a-ef6338fa89ac","display-name":"Test Tag"}}}}', '{}', 1, 2, NULL, 'native', true, 2, NULL, NULL, false, NULL, NULL, '[{"display_name":"duration","field_ref":["field","duration",{"base-type":"type/Text"}],"name":"duration","base_type":"type/Text","effective_type":"type/Text","semantic_type":null,"fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":2.0}}}}]', NULL, 'Zbk0P2TVAHV9TgfoTLJBV', '[{"id":"affebf1f-7bab-4b3d-a023-d46693f7896a","type":"category","target":["variable",["t