INSERT INTO public.report_card VALUES (122, '2025-03-19 16:44:22.155968+01', '2025-07-16 08:01:26.893334+02', 'Aggregate - New or Changed Methods - Duplicate', 'Changes not tested in Build compared to Baseline Build.', 'pie', '{"type":"native","database":2,"native":{"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT * \r\n        FROM raw_data.get_materialized_build_coverage(\r\n        input_group_id => split_part({{build}}, '':'', 1),\r\n        input_app_id => split_part({{build}}, '':'', 2),\r\n        input_build_id => {{build}},\r\n        input_aggregated_coverage => true,\r\n        input_baseline_build_id => {{baseline}}\r\n        [[, input_test_tag => {{test_tag}} ]]\r\n        [[, input_env_id => {{env}} ]]\r\n        [[, input_branch => {{branch}} ]]\r\n    )\r\n)\r\nSELECT\r\n    ''Fully Tested'' AS metric,\r\n    aggregated_tested_changes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Partially Tested'' as metric,\r\n    aggregated_partially_tested_changes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Not Tested'' as metric,\r\n    (total_changes - aggregated_tested_changes - aggregated_partially_tested_changes) AS value\r\nFROM BuildCoverage","template-tags":{"build":{"type":"text","name":"build","id":"b0fa82b0-2234-4e10-bdde-fde786222085","display-name":"Build","required":true},"branch":{"type":"text","name":"branch","id":"06790b5d-5d2c-4abe-9c40-b0aae94636ff","display-name":"Branch"},"baseline":{"type":"text","name":"baseline","id":"10a4e87d-9446-4021-9de0-a1c5a040103d","display-name":"Baseline","required":true},"test_tag":{"type":"text","name":"test_tag","id":"803271f6-0767-489b-9bb6-cd103d0b58ef","display-name":"Test Tag"},"env":{"type":"text","name":"env","id":"377b779c-d016-4ec6-8520-8d1ca75a2a44","display-name":"Env"}}}}', '{"table.columns":[{"name":"metric","fieldRef":["field","metric",{"base-type":"type/Text"}],"enabled":true},{"name":"value","fieldRef":["field","value",{"base-type":"type/Integer"}],"enabled":