INSERT INTO public.report_card VALUES (67, '2025-02-18 16:46:00.74098+01', '2025-06-30 12:25:02.284647+02', 'Time has been saved OLD', NULL, 'scalar', '{"database":2,"type":"native","native":{"template-tags":{"test_session":{"type":"text","name":"test_session","id":"db11acfd-222f-43da-81ad-99c299fea5de","display-name":"Test Session"},"build":{"type":"text","name":"build","id":"7ce9ac69-baf2-46a3-a6c1-baa9254eb955","display-name":"Build"}},"query":"WITH\r\n  SmartSkippedTests AS (\r\n\tSELECT \t\t\r\n\t\tSUM(td.avg_duration) AS time_saved\r\n\tFROM raw_data.test_launches tl\t\r\n\tJOIN raw_data.view_test_definitions td ON td.test_definition_id = tl.test_definition_id\r\n\tJOIN raw_data.test_session_builds tsb ON tsb.test_session_id = tl.test_session_id \r\n\tJOIN raw_data.builds b ON b.id = tsb.build_id\r\n\tWHERE tl.result = ''SMART_SKIPPED''\r\n\t  AND td.avg_duration IS NOT NULL\r\n\t  [[AND b.app_id IN (SELECT app_id FROM raw_data.builds WHERE id = {{build}})]]\r\n\t  [[AND tsb.test_session_id = {{test_session}}]]\r\n  )\r\nSELECT\r\n\tCOALESCE(raw_data.format_duration_rounded(SUM(tests.time_saved)::INT), ''0ms'') AS duration\r\nFROM SmartSkippedTests tests;"}}', '{"table.pivot_column":"smart_skipped","table.cell_column":"duration","column_settings":{"[\"name\",\"duration\"]":{"scale":0.001,"suffix":" sec"}}}', 1, 2, NULL, 'native', true, 3, NULL, NULL, false, NULL, NULL, '[{"display_name":"duration","field_ref":["field","duration",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"duration","semantic_type":null,"fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":3.0}}}}]', NULL, 'ZRu27L5cFdGvBk6mPlknx', '[{"id":"db11acfd-222f-43da-81ad-99c299fea5de","type":"category","target":["variable",["template-tag","test_session"]],"name":"Test Session","slug":"test_session"},{"id":"7ce9ac69-baf2-46a3-a6c1-baa9254eb955",