INSERT INTO public.report_card VALUES (157, '2025-06-30 12:08:26.248121+02', '2025-07-01 09:30:48.979141+02', 'Build Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT b.build_id, v.probes, v.methods, v.metric\r\nFROM metrics.builds b\r\nJOIN metrics.get_builds_with_coverage(input_build_id => b.build_id) c ON true\r\nCROSS JOIN LATERAL UNNEST(\r\n\tARRAY[c.isolated_covered_probes, c.aggregated_covered_probes - c.isolated_covered_probes, c.total_probes - c.aggregated_covered_probes],\r\n\tARRAY[c.isolated_tested_methods, c.aggregated_tested_methods - c.isolated_tested_methods, c.total_methods - c.aggregated_tested_methods],\r\n\tARRAY[''Isolated Covered'', ''Covered'', ''Gaps'']  \r\n) AS v(probes, methods, metric)"}}', '{"table.pivot_column":"build_id","table.cell_column":"probes"}', 1, 2, NULL, 'native', true, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"build_id","field_ref":["field","build_id",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"build_id","semantic_type":null,"fingerprint":{"global":{"distinct-count":2,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":26.0}}}},{"display_name":"probes","field_ref":["field","probes",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"probes","semantic_type":null,"fingerprint":{"global":{"distinct-count":6,"nil%":0.0},"type":{"type/Number":{"min":0.0,"q1":61.0,"q3":508.0,"max":617.0,"sd":248.9929048520593,"avg":334.6666666666667}}}},{"display_name":"methods","field_ref":["field","methods",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"methods","semantic_type":null,"fingerprint":{"global":{"distinct-count":6,"nil%":0.0},"type":{"type/Number":{"min":0.0,"q1":35.0,"q3":278.0,"max":322.0,"sd":138.83047215939303,"avg":123.5}}}},{"display_name":"metric","field_ref":["field","metric",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"metric","semantic_type":null,"fingerprint":{"global":{"distinct-count":3,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":9.0}}}}]', 2, '3rsd-zcT5oBZ1C0lcz_aa', '[]', '[]', true, 'v0.53.7.4 (0154e20)', 'model', NULL, NULL, '2025-06-30 12:22:36.664409+02', 8, true, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (150, '2025-04-30 11:29:35.69223+02', '2025-06-25 14:02:46.001588+02', 'Test Launch Coverage', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"ab59fd75-b5d6-436b-8123-40b96f24d664","display-name":"Build"},"test_launch":{"type":"text","name":"test_launch","id":"43347459-4d0f-438b-ad9f-f178bcf520e3","display-name":"Test Launch"},"package_name":{"type":"text","name":"package_name","id":"1e6d044e-c553-4e23-84f9-068bb4e368cc","display-name":"Package Name"},"class_name":{"type":"text","name":"class_name","id":"ad3b3194-15d0-4e3b-99b7-c5267bd8654b","display-name":"Class Name"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT \r\n\t\ttotal_probes,\r\n\t\tisolated_covered_probes,\r\n\t\taggregated_covered_probes\r\n\tFROM metrics.get_builds_with_coverage(\r\n\t    input_build_id => {{build}},\r\n\t\tinput_test_launch_id => {{test_launch}}\r\n\t\t[[, input_package_name_pattern => {{package_name}} || ''%'']]\r\n\t\t[[, input_class_name_pattern => {{class_name}} || ''%'']]\r\n\t)\r\n)\r\nSELECT\r\n    ''Isolated Coverage'' AS metric,\r\n    isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Aggregated Coverage'' AS metric,\r\n    aggregated_covered_probes - isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Gaps'' as metric,\r\n    total_probes - aggregated_covered_probes AS value\r\nFROM BuildCoverage"}}', '{"pie.sort_rows":false,"pie.rows":[{"key":"Isolated Coverage","name":"Covered","originalName":"Isolated Coverage","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Aggregated Coverage","name":"Covered by other tests","originalName":"Aggregated Coverage","color":"#87BCEC","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Gaps","name":"Gaps","originalName":"Gaps","color":"#ED8535","defaultColor":false,"enabled":true,"hidden":false,