INSERT INTO public.report_card VALUES (135, '2025-03-28 13:10:32.593349+01', '2025-06-30 12:23:45.089138+02', 'Isolated - New or Changed Code', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"b0fa82b0-2234-4e10-bdde-fde786222085","display-name":"Build","required":true},"baseline":{"type":"text","name":"baseline","id":"f03b9234-08fc-4c9a-b51a-53211c8ad752","display-name":"Baseline","required":true},"env":{"type":"text","name":"env","id":"c3370bcf-c868-4865-8cc5-56e72a2260f5","display-name":"Env"},"branch":{"type":"text","name":"branch","id":"de6ad949-a030-4a7f-9876-86cb3cd20e31","display-name":"Branch"},"test_tag":{"type":"text","name":"test_tag","id":"d2c0b972-47f4-449f-a063-3b69859788e0","display-name":"Test Tag"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT * \r\n        FROM raw_data.get_build_coverage_v2(\r\n        input_build_id => {{build}},\r\n        input_aggregated_coverage => false,\r\n        input_materialized => true,\r\n        input_baseline_build_id => {{baseline}}\r\n        [[, input_test_tag => {{test_tag}} ]]\r\n        [[, input_env_id => {{env}} ]]\r\n        [[, input_branch => {{branch}} ]]\r\n    )\r\n)\r\nSELECT\r\n    ''Total Coverage'' AS metric,\r\n    isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Gaps'' as metric,\r\n    (total_probes - isolated_covered_probes) AS value\r\nFROM BuildCoverage"}}', '{"table.columns":[{"name":"value","fieldRef":["field","value",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"metric","fieldRef":["field","metric",{"base-type":"type/Text"}],"enabled":true}],"table.column_formatting":[{"columns":["__covered_probes"],"type":"single","operator":"=","value":0,"color":"#EF8C8C","highlight_row":true},{"max_value":1,"color":"#509EE3","columns":["__probes_coverage_ratio"],"value":"","type":"range","colors":["#ED6E6E","#F9CF48","#84BB4C"],"highlight_row":false,"min_value":0,"min_type":"custom",