INSERT INTO public.report_card VALUES (46, '2024-07-19 16:12:59.699863+02', '2025-06-30 12:55:48.937761+02', 'Code Coverage - Probes', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"f851d33d-20ce-4739-bf67-ceb734ac6fe4","display-name":"Build"},"baseline":{"type":"text","name":"baseline","id":"cea9941b-6330-4474-ae1b-6c1d3dbd886d","display-name":"Baseline"},"test_tag":{"type":"text","name":"test_tag","id":"d1568470-274a-42c9-872b-74631ae362b0","display-name":"Test Tag"},"env":{"type":"text","name":"env","id":"a0d25db1-2b3b-414e-bd10-0420e316520e","display-name":"Env"},"branch":{"type":"text","name":"branch","id":"cf530b72-3f0a-4813-9a9c-14ebe61da024","display-name":"Branch"},"test_session":{"type":"text","name":"test_session","id":"59dbe437-97e3-4e09-9eec-b1f07b2b0f3d","display-name":"Test Session"},"test_launch":{"type":"text","name":"test_launch","id":"72929e60-b307-4fdf-a2e1-697d42a2c605","display-name":"Test Launch"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT * \r\n        FROM metrics.get_builds_with_coverage(\r\n        input_build_id => {{build}}\r\n        [[, input_test_session_id => {{test_session}}]]\r\n        [[, input_test_launch_id => {{test_launch}}]]\r\n        [[, input_baseline_build_id => {{baseline}}]]\r\n        [[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n        [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n        [[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\r\n    )\r\n)\r\nSELECT\r\n    ''Isolated Coverage'' AS metric,\r\n    isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Aggregated Coverage'' AS metric,\r\n    aggregated_covered_probes - isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Gaps'' as metric,\r\n    total_probes - aggregated_covered_probes AS value\r\nFROM BuildCoverage\r\n"}}', '{"pie.slice_threshold":1,"pie.colors"