INSERT INTO public.report_card VALUES (149, '2025-04-30 11:26:05.787244+02', '2025-11-11 17:54:24.740496+01', 'Test Launch Coverage', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"6ce607c7-aeb7-4c0a-88ca-332f52238dab","display-name":"Build"},"test_launch":{"type":"text","name":"test_launch","id":"14daf3d4-0027-4956-ba79-e2035972675b","display-name":"Test Launch"}},"query":"WITH\r\nBuildCoverage AS (\r\n    SELECT \r\n\t\tSUM(probes_count) AS total_probes,\r\n\t\tSUM(isolated_covered_probes) AS isolated_covered_probes,\r\n\t\tSUM(aggregated_covered_probes) AS aggregated_covered_probes\r\n\tFROM raw_data.get_methods_tests_coverage(\r\n\t    input_build_id => {{build}},\r\n\t\tinput_test_launch_id => {{test_launch}},\r\n\t\tinput_aggregated_coverage => true\r\n\t)\r\n)\r\nSELECT\r\n    ''Isolated Coverage'' AS metric,\r\n    isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Aggregated Coverage'' AS metric,\r\n    aggregated_covered_probes - isolated_covered_probes AS value\r\nFROM BuildCoverage\r\nUNION ALL\r\nSELECT\r\n    ''Gaps'' as metric,\r\n    total_probes - aggregated_covered_probes AS value\r\nFROM BuildCoverage"}}', '{"pie.metric":"aggregated_covered_probes","pie.dimension":["package_name"],"pie.rows":[{"key":"Isolated Coverage","name":"Covered in current test","originalName":"Isolated Coverage","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Aggregated Coverage","name":"Covered in other tests","originalName":"Aggregated Coverage","color":"#87BCEC","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Gaps","name":"Gaps","originalName":"Gaps","color":"#F2A86F","defaultColor":true,"enabled":true,"hidden":false,"isOther":false},{"isOther":false,"hidden":true,"enabled":false,"defaultColor":true,"color":"#509EE3","originalName":"net/n2oapp/framework/api/metadata/global/view/widget","name":"ne