INSERT INTO public.report_card VALUES (70, '2025-02-19 14:59:43.727355+01', '2025-06-30 12:41:20.117436+02', 'Table - Tests To Skip', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"3ce92c0c-ae2a-42dd-b96f-b306d002d986","display-name":"Build"},"branch":{"type":"text","name":"branch","id":"1a713460-d8de-42c7-8f1a-3db7fdcfadb8","display-name":"Branch"},"env":{"type":"text","name":"env","id":"69bb0504-7e5a-42eb-b990-96caea0bacf9","display-name":"Env"},"test_tag":{"type":"text","name":"test_tag","id":"0e88a6a4-3a24-499c-ab94-b7419b176d00","display-name":"Test Tag"}},"query":"SELECT DISTINCT\r\n  td.test_path,\r\n  td.test_name,\r\n  td.test_duration_avg,\r\n  metrics.format_duration_rounded(td.test_duration_avg::bigint) AS test_duration_avg_formatted,\r\n  td.test_runner,\r\n  td.test_tags,\r\n  array_to_string(td.test_tags, '', '') AS test_tags_formatted\r\nFROM metrics.get_recommended_tests(\r\n\t\tinput_build_id => {{build}},\r\n\t\ttests_to_skip => true\r\n\t\t[[, input_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n\t\t[[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\r\n\t\t[[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n\t) rt\r\nJOIN metrics.test_definitions_with_statistics td ON td.group_id = rt.group_id AND td.test_definition_id = rt.test_definition_id"}}', '{"table.columns":[{"name":"test_path","enabled":true},{"name":"test_name","enabled":true},{"name":"test_duration_avg","enabled":false},{"name":"test_duration_avg_formatted","enabled":true},{"name":"test_runner","enabled":true},{"name":"test_tags","enabled":false},{"name":"test_tags_formatted","enabled":true}],"table.pivot_column":"__test_runner","table.cell_column":"duration","column_settings":{"[\"name\",\"test_path\"]":{"column_title":"Path"},"[\"name\",\"test_name\"]":{"column_title":"Test Name"},"[\"name\",\"test_duration_avg_formatted\"]":{"column_title":"Duration Avg."},"[\"name\",\"test_runner\"]":