INSERT INTO public.report_card VALUES (72, '2025-02-21 10:14:31.584186+01', '2025-11-11 18:15:50.290275+01', 'Changes by Builds - Methods', NULL, 'line', '{"database":2,"type":"native","native":{"template-tags":{"baseline":{"type":"text","name":"baseline","id":"fd208481-c956-4fc8-86b0-fada3b63ef9e","display-name":"Baseline","required":false},"branch":{"type":"text","name":"branch","id":"469993df-3574-4151-97ae-620f3fa4af68","display-name":"Branch"},"app_env":{"type":"text","name":"app_env","id":"11a2d930-d394-4008-ac5a-6d597bbafa01","display-name":"App Env"},"test_tag":{"type":"text","name":"test_tag","id":"89a064cb-5352-483f-aa1e-f17d1bf2676e","display-name":"Test Tag"},"group":{"type":"text","name":"group","id":"54d8a06c-0c59-4ab4-87bd-1fa92894c827","display-name":"Group"},"app":{"type":"text","name":"app","id":"90660d1d-2226-49a7-b70f-81fa6f5291ec","display-name":"App"},"limit":{"type":"number","name":"limit","id":"249c9cbf-f048-4d27-965f-ea0011efec0d","display-name":"Limit","default":"100","widget-type":null,"required":true}},"query":"WITH\r\nbuilds AS (\r\n    SELECT\r\n    \tb.group_id,\r\n    \tb.app_id,\r\n    \tb.build_id,\r\n    \tCASE \r\n    \t    WHEN b.build_version IS NOT NULL THEN b.build_version\r\n    \t    ELSE LEFT(b.version_id, 7)\r\n    \tEND AS version_id,\r\n    \tb.committed_at,\r\n    \tb.created_at\r\n    FROM metrics.builds b\r\n    WHERE b.group_id = {{group}}\r\n        AND b.app_id = {{app}}\r\n        AND b.branch LIKE {{branch}}\r\n        [[ AND {{app_env}} = ANY(b.app_env_ids) ]]\r\n    ORDER BY b.created_at DESC\r\n    LIMIT {{limit}}\r\n)\r\nSELECT \r\n  b.build_id AS \"Build ID\",\r\n  b.version_id AS \"Version\",\r\n  c.total_methods AS \"Total Changes\",\r\n  c.isolated_tested_methods AS \"Isolated Tested Changes\",\r\n  c.aggregated_tested_methods AS \"Aggregated Tested Changes\"\r\nFROM metrics.get_builds_with_coverage(\r\n\tinput_build_ids => array(select build_id from builds)\r\n\t, input_coverage_branches => array[{{branch}}]::varchar[]\r\n\t, input_baseline_build_id => {{baseline}}\r\n\t[[, input_coverage_app_env_ids => array[{{app_env}}]::varchar[] ]]\r\n\t[[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n) c\r\nJOIN builds b ON b.group_id = c.group_id AND b.app_id = c.app_id AND b.build_id = c.build_id\r\nORDER BY b.committed_at ASC, b.created_at ASC"}}', '{"graph.show_goal":false,"graph.show_values":false,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Builds","graph.y_axis.scale":"linear","graph.y_axis.auto_split":false,"graph.metrics":["Total Changes","Isolated Tested Changes","Aggregated Tested Changes"],"graph.y_axis.axis_enabled":true,"graph.series_order":null,"series_settings":{"Total Changes":{"color":"#E75454","title":"Total Methods"},"Isolated Tested Changes":{"color":"#227FD2","title":"Tested","display":"area"},"Aggregated Tested Changes":{"color":"#87BCEC","title":"Tested in other builds","display":"area"}},"graph.y_axis.auto_range":true,"graph.dimensions":["Version"]}', 1, 2, NULL, 'native', false, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"Build ID","field_ref":["field","Build ID",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"Build ID","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Text":{"percent-json":null,"percent-url":null,"percent-email":null,"percent-state":null,"average-length":null}}}},{"display_name":"Version","field_ref":["field","Version",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"Version","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Text":{"percent-json":null,"percent-url":null,"percent-email":null,"percent-state":null,"average-length":null}}}},{"display_name":"Total Changes","field_ref":["field","Total Changes",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"Total Changes","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Number":{"min":null,"q1":null,"q3":null,"max":null,"sd":null,"avg":null}}}},{"display_name":"Isolated Tested Changes","field_ref":["field","Isolated Tested Changes",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"Isolated Tested Changes","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Number":{"min":null,"q1":null,"q3":null,"max":null,"sd":null,"avg":null}}}},{"display_name":"Aggregated Tested Changes","field_ref":["field","Aggregated Tested Changes",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"Aggregated Tested Changes","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Number":{"min":null,"q1":null,"q3":null,"max":null,"sd":null,"avg":null}}}}]', NULL, 'GWiF7El3cGVHXVy4jVyN-', '[{"id":"fd208481-c956-4fc8-86b0-fada3b63ef9e","type":"category","target":["variable",["template-tag","baseline"]],"name":"Baseline","slug":"baseline","required":false},{"id":"469993df-3574-4151-97ae-620f3fa4af68","type":"category","target":["variable",["template-tag","branch"]],"name":"Branch","slug":"branch"},{"id":"11a2d930-d394-4008-ac5a-6d597bbafa01","type":"category","target":["variable",["template-tag","app_env"]],"name":"App Env","slug":"app_env"},{"id":"89a064cb-5352-483f-aa1e-f17d1bf2676e","type":"category","target":["variable",["template-tag","test_tag"]],"name":"Test Tag","slug":"test_tag"},{"id":"54d8a06c-0c59-4ab4-87bd-1fa92894c827","type":"category","target":["variable",["template-tag","group"]],"name":"Group","slug":"group"},{"id":"90660d1d-2226-49a7-b70f-81fa6f5291ec","type":"category","target":["variable",["template-tag","app"]],"name":"App","slug":"app"},{"id":"249c9cbf-f048-4d27-965f-ea0011efec0d","type":"number/=","target":["variable",["template-tag","limit"]],"name":"Limit","slug":"limit","default":"100","requ