INSERT INTO public.report_card VALUES (169, '2025-11-11 17:27:49.57597+01', '2025-11-11 17:31:57.479362+01', 'Test Session - Classes Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"28c8e3af-50db-4e01-84ba-2ebd1ea897a2","display-name":"Build"},"package":{"type":"text","name":"package","id":"8b43f735-c46a-415a-934d-3f54e91dde5e","display-name":"Package"},"test_session":{"type":"text","name":"test_session","id":"1bc8cf1f-7a0f-46bf-955e-c02a86984a12","display-name":"Test Session"},"app_env":{"type":"text","name":"app_env","id":"8da9f53b-5f9f-4a06-8c0c-f97f441ae5bc","display-name":"App Env"},"test_tag":{"type":"text","name":"test_tag","id":"f90666d1-95e3-42e2-8b64-15e7bc6af99d","display-name":"Test Tag"}},"query":"WITH\nMethodsCoverage AS (\n\tSELECT\n\t\tREVERSE(\n\t\t\tSUBSTRING(\n\t\t\t\tREVERSE(class_name) FROM POSITION(''/'' IN REVERSE(class_name)) + 1)) AS package_name,\n\t\t*\n\tFROM metrics.get_methods_with_coverage_by_test_session(\n\t    input_build_id => {{build}},\n\t\tinput_test_session_id => {{test_session}},\n\t\tinput_package_name_pattern => {{package}}||''%''\n\t    [[, input_coverage_app_env_ids => array[{{app_env}}]::varchar[] ]]\n        [[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\n    )\n)\nSELECT\n\tpackage_name,\n\tclass_name,\n\tSUM(probes_count) as probes_count,\n\tSUM(covered_probes) as covered_probes,\n\tSUM(missed_probes) as missed_probes,\n\tCAST(SUM(covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio\nFROM MethodsCoverage\nGROUP BY package_name, class_name\nORDER BY\n    missed_probes DESC"}}', '{"graph.show_goal":false,"graph.show_values":false,"scatter.bubble":"probes_count","table.columns":[{"name":"package_name","fieldRef":["field","package_name",{"base-type":"type/Text"}],"enabled":true},{"name":"class_name","enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/Big