INSERT INTO public.report_card VALUES (65, '2025-02-18 16:41:30.448497+01', '2025-10-23 14:48:35.544521+02', 'Time will be saved', NULL, 'scalar', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"affebf1f-7bab-4b3d-a023-d46693f7896a","display-name":"Build"},"branch":{"type":"text","name":"branch","id":"bc3337f2-c020-4179-887a-91869546f017","display-name":"Branch"},"env":{"type":"text","name":"env","id":"3e43c992-7f1b-4b39-a6ed-b756b8ca026c","display-name":"Env"},"test_tag":{"type":"text","name":"test_tag","id":"ced80ceb-ee7d-45aa-824a-ef6338fa89ac","display-name":"Test Tag"},"baseline_build":{"type":"text","name":"baseline_build","id":"f2de3213-16d7-43c1-b1a8-a2748e1c0c7e","display-name":"Baseline Build"}},"query":"SELECT \r\n    COALESCE(metrics.format_duration_rounded(SUM(td.test_duration_avg)::INT), ''0ms'') AS duration\r\nFROM metrics.get_recommended_tests_v2 (\r\n    input_build_id => {{build}},\r\n    input_test_impact_statuses => ''{NOT_IMPACTED}''\r\n    [[, input_baseline_until_build_id => {{baseline_build}} ]] \r\n    [[, input_baseline_build_branches => array[{{branch}}]::varchar[] ]] \r\n    [[, input_test_tags => array[{{test_tag}}]::varchar[] ]] \r\n    [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n  ) AS skips\r\nJOIN metrics.test_definitions_with_statistics td ON td.group_id = skips.group_id AND td.test_path = skips.test_path AND td.test_name = skips.test_name"}}', '{}', 1, 2, NULL, 'native', false, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"duration","field_ref":["field","duration",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"duration","semantic_type":null,"fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":3.0}}}}]', NULL, 'imUz0QmWOc7Yq-0URgemQ', '[{"id":"affebf1f-7bab-4b3d-a023-d46693f7896a","type":"category","target":["variable",["template-tag","build"]],"name":"Build","slug":"build"},{"id":"bc3337f2-c020-4179-887a-91869546f017","type":"category","target":["variable",["template-tag","branch"]],"name":"Branch","slug":"branch"},{"id":"3e43c992-7f1b-4b39-a6ed-b756b8ca026c","type":"category","target":["variable",["template-tag","env"]],"name":"Env","slug":"env"},{"id":"ced80ceb-ee7d-45aa-824a-ef6338fa89ac","type":"category","target":["variable",["template-tag","test_tag"]],"name":"Test Tag","slug":"test_tag"},{"id":"f2de3213-16d7-43c1-b1a8-a2748e1c0c7e","type":"category","target":["variable",["template-tag","baseline_build"]],"name":"Baseline Build","slug":"baseline_build"}]', '[]', true, 'v0.48.6 (b8818f9)', 'question', NULL, NULL, '2025-11-12 10:31:52.504454+01', 999, false, NULL, NULL, NULL);
