INSERT INTO public.report_card VALUES (61, '2025-01-22 16:41:43.172821+01', '2025-08-27 10:40:55.826402+02', 'Test Tags', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT unnest(test_tags) as test_tag\nFROM metrics.test_definitions\nORDER BY test_tag"}}', '{"table.pivot_column":"tag","table.cell_column":"test_tag"}', 1, 2, NULL, 'native', false, 3, NULL, NULL, false, NULL, NULL, '[{"display_name":"test_tag","field_ref":["field","test_tag",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"test_tag","semantic_type":null,"fingerprint":{"global":{"distinct-count":3,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":6.666666666666667}}}}]', 3, '7jlX9eq8pF3N6-xRfTRyG', '[]', '[]', true, 'v0.48.6 (b8818f9)', 'model', NULL, NULL, '2025-11-11 18:04:42.063172+01', 11, false, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (90, '2025-02-24 12:47:53.862128+01', '2025-11-11 17:55:37.078383+01', 'Tests - Classes Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"test_launch":{"type":"text","name":"test_launch","id":"2ce49555-c412-44d9-8470-37f8916c6adc","display-name":"Test Launch"},"build":{"type":"text","name":"build","id":"28c8e3af-50db-4e01-84ba-2ebd1ea897a2","display-name":"Build"},"package_name":{"type":"text","name":"package_name","id":"7b82f2c9-e567-4268-bd31-18b4b9dfbd61","display-name":"Package Name"}},"query":"WITH\r\nMethodsCoverage AS (\r\n\tSELECT\r\n\t\tREVERSE(\r\n\t\t\tSUBSTRING(\r\n\t\t\t\tREVERSE(classname) FROM POSITION(''/'' IN REVERSE(classname)) + 1)) AS package_name,\r\n\t\t*\r\n\tFROM metrics.get_methods_with_coverage(\r\n\t    input_build_id => {{build}},\r\n\t\tinput_test_launch_id => {{test_launch}},\r\n\t   \tinput_package_name_pattern => {{package_name}} || ''%''\r\n\t)  \r\n)\r\nSELECT\r\n    package_name,\r\n\tclassname,\r\n\tSUM(probes_count) as probes_count,\r\n\tSUM(aggregated_covered_probes - isolated_covered_probes) as covered_probes,\r\n\tSUM(aggregated_missed_probes) as missed_probes,\r\n\tCAST(SUM(aggregated_covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio,\r\n\tSUM(isolated_covered_probes) as isolated_covered_probes\r\nFROM MethodsCoverage\r\nGROUP BY package_name, classname\r\nORDER BY\r\n    covered_probes DESC;"}}', '{"graph.show_goal":false,"graph.show_values":false,"scatter.bubble":"probes_count","table.columns":[{"name":"package_name","fieldRef":["field","package_name",{"base-type":"type/Text"}],"enabled":true},{"name":"classname","fieldRef":["field","classname",{"base-type":"type/Text"}],"enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"isolated_covered_probes","fieldRef":["field","isolated_covered_probes",{"base-type":"type/BigInteger"}],"enabled":true