INSERT INTO public.report_card VALUES (91, '2025-02-24 12:47:53.862128+01', '2025-11-11 17:55:45.150482+01', 'Tests - Package Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"test_launch":{"type":"text","name":"test_launch","id":"98054d74-6e17-454a-9fcc-78736ed239fd","display-name":"Test Launch"},"build":{"type":"text","name":"build","id":"089b65d5-7b8a-4cb6-96cd-07e91a1d233e","display-name":"Build"}},"query":"WITH\r\nMethodsCoverage AS (\r\n\tSELECT\r\n\t\tREVERSE(\r\n\t\t\tSUBSTRING(\r\n\t\t\t\tREVERSE(classname) FROM POSITION(''/'' IN REVERSE(classname)) + 1)) AS package_name,\r\n\t\t*\r\n\tFROM metrics.get_methods_with_coverage(\r\n\t    input_build_id => {{build}},\r\n\t\tinput_test_launch_id => {{test_launch}}\r\n\t)\r\n)\r\nSELECT\r\n\tpackage_name,\r\n\tSUM(probes_count) as probes_count,\r\n\tSUM(aggregated_covered_probes - isolated_covered_probes) as aggregated_covered_probes,\r\n\tSUM(aggregated_missed_probes) as missed_probes,\r\n\tCAST(SUM(aggregated_covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio,\r\n\tSUM(isolated_covered_probes) as isolated_covered_probes\r\nFROM MethodsCoverage\r\nGROUP BY package_name\r\nORDER BY\r\n    aggregated_covered_probes DESC;"}}', '{"graph.show_goal":false,"graph.show_values":false,"scatter.bubble":"probes_count","table.columns":[{"name":"package_name","fieldRef":["field","package_name",{"base-type":"type/Text"}],"enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"isolated_covered_probes","fieldRef":["field","isolated_covered_probes",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"aggregated_covered_probes","enabled":true},{"name":"missed_probes","fieldRef":["field","missed_probes",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"probes_coverage_ratio","fieldRef":["field","probes_coverage_ratio",{"base-type":"type/Float"}],"enabled":true}],"pie.dimension