_covered_probes",{"base-type":"type/BigInteger"}],"base_type":"type/BigInteger","effective_type":"type/BigInteger","name":"aggregated_covered_probes","semantic_type":null,"fingerprint":{"global":{"distinct-count":13,"nil%":0.0},"type":{"type/Number":{"min":5.0,"q1":9.0,"q3":50.0,"max":185.0,"sd":48.56308913540845,"avg":40.714285714285715}}}},{"display_name":"missed_probes","field_ref":["field","missed_probes",{"base-type":"type/BigInteger"}],"base_type":"type/BigInteger","effective_type":"type/BigInteger","name":"missed_probes","semantic_type":null,"fingerprint":{"global":{"distinct-count":12,"nil%":0.0},"type":{"type/Number":{"min":0.0,"q1":4.0,"q3":21.0,"max":224.0,"sd":57.271859879577285,"avg":27.285714285714285}}}},{"display_name":"probes_coverage_ratio","field_ref":["field","probes_coverage_ratio",{"base-type":"type/Float"}],"base_type":"type/Float","effective_type":"type/Float","name":"probes_coverage_ratio","semantic_type":null,"fingerprint":{"global":{"distinct-count":13,"nil%":0.0},"type":{"type/Number":{"min":0.25333333333333335,"q1":0.5454545454545454,"q3":0.8974358974358975,"max":1.0,"sd":0.2394535839780427,"avg":0.6909141073873688}}}},{"display_name":"isolated_covered_probes","field_ref":["field","isolated_covered_probes",{"base-type":"type/BigInteger"}],"base_type":"type/BigInteger","effective_type":"type/BigInteger","name":"isolated_covered_probes","semantic_type":null,"fingerprint":{"global":{"distinct-count":6,"nil%":0.0},"type":{"type/Number":{"min":0.0,"q1":0.0,"q3":5.0,"max":18.0,"sd":5.812548002873979,"avg":3.357142857142857}}}}]', NULL, 'FsS0f6qKqNZATPQBmYdX2', '[{"id":"98054d74-6e17-454a-9fcc-78736ed239fd","type":"category","target":["variable",["template-tag","test_launch"]],"name":"Test Launch","slug":"test_launch"},{"id":"089b65d5-7b8a-4cb6-96cd-07e91a1d233e","type":"category","target":["variable",["template-tag","build"]],"name":"Build","slug":"build"}]', '[]', true, 'v0.48.6 (b8818f9)', 'question', NULL, NULL, '2025-06-25 11:55:11.656976+