INSERT INTO public.report_card VALUES (137, '2025-04-01 17:30:04.113761+02', '2025-11-11 15:22:08.487585+01', 'Select Baseline Build', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"939c40de-f837-418c-973c-53e92438e1d3","display-name":"Build"},"branch":{"type":"text","name":"branch","id":"4a0902a1-1428-40bb-8ee4-e3215984d7c9","display-name":"Branch"}},"query":"SELECT \r\n    b.build_id,\r\n    b.version_id,\r\n    b.branch,\r\n    c.identity_ratio,\r\n    (c.target_total_methods - c.target_equal_methods)||'' new or modified methods'' AS changes\r\nFROM metrics.get_similar_builds(\r\n    input_build_id => {{build}}\r\n    [[, input_branches => array[{{branch}}]::varchar[] ]]\r\n) c\r\nJOIN metrics.builds b ON b.group_id = c.group_id AND b.app_id = c.app_id AND b.build_id = c.build_id\r\nORDER BY c.identity_ratio DESC\r\n"}}', '{"table.columns":[{"name":"build_id","enabled":false},{"name":"version_id","enabled":true},{"name":"branch","enabled":true},{"name":"changes","enabled":true},{"name":"identity_ratio","enabled":true}],"table.pivot_column":"branch","table.cell_column":"total_changes","column_settings":{"[\"name\",\"build_id\"]":{"column_title":"Build ID"},"[\"name\",\"version_id\"]":{"column_title":"Version"},"[\"name\",\"branch\"]":{"column_title":"Branch"},"[\"name\",\"identity_ratio\"]":{"number_style":"percent","column_title":"Identity "},"[\"name\",\"changes\"]":{"column_title":"Changes"}}}', 1, 2, NULL, 'native', false, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"build_id","field_ref":["field","build_id",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"build_id","semantic_type":null,"fingerprint":{"global":{"distinct-count":10,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":37.0}}}},{"display_name":"version_id","field_ref":["field","version_id",{"base-type":"type/