INSERT INTO public.report_card VALUES (136, '2025-03-31 14:53:47.34088+02', '2025-11-11 18:16:10.391962+01', 'Changes by Builds - Code', NULL, 'line', '{"database":2,"type":"native","native":{"template-tags":{"group":{"type":"text","name":"group","id":"46c13019-4546-4b72-8834-d339f3cc8477","display-name":"Group","required":true},"app":{"type":"text","name":"app","id":"6aee7238-8689-4140-bd00-5e457ee5ed72","display-name":"App","required":true},"baseline":{"type":"text","name":"baseline","id":"fd208481-c956-4fc8-86b0-fada3b63ef9e","display-name":"Baseline","required":true},"branch":{"type":"text","name":"branch","id":"469993df-3574-4151-97ae-620f3fa4af68","display-name":"Branch","required":false},"app_env":{"type":"text","name":"app_env","id":"8490731d-c08b-4d39-b65c-aaaa043c71d0","display-name":"App Env"},"test_tag":{"type":"text","name":"test_tag","id":"f600f685-2adb-4e22-8b7f-fbfd149f891e","display-name":"Test Tag"},"limit":{"type":"number","name":"limit","id":"1f4ae545-b76f-4ca4-9bec-615b3c4d8a10","display-name":"Limit","default":"100","required":true,"widget-type":null}},"query":"WITH\r\nbuilds AS (\r\n    SELECT\r\n    \tb.group_id,\r\n    \tb.app_id,\r\n    \tb.build_id,\r\n    \tCASE \r\n    \t    WHEN b.build_version IS NOT NULL THEN b.build_version\r\n    \t    ELSE LEFT(b.version_id, 7)\r\n    \tEND AS version_id,\r\n    \tb.committed_at,\r\n    \tb.created_at\r\n    FROM metrics.builds b\r\n    WHERE b.group_id = {{group}}\r\n        AND b.app_id = {{app}}\r\n        AND b.branch LIKE {{branch}}\r\n        [[ AND {{app_env}} = ANY(b.app_env_ids) ]]\r\n    ORDER BY b.created_at DESC\r\n    LIMIT {{limit}}\r\n)\r\nSELECT \r\n  b.build_id AS \"Build ID\",\r\n  b.version_id AS \"Version\",\r\n  c.total_probes AS \"Total Probes\",\r\n  c.aggregated_covered_probes AS \"Covered in other builds\",\r\n  c.isolated_covered_probes AS \"Covered\",\r\n  c.total_methods AS \"Total Changes\",\r\n  c.isolated_tested_methods AS \"Tested\",\r\n  c.aggregated_tested_methods AS \"Tested in other builds\"\r\nFROM metrics.get_builds_with_coverage(\r\n\tinput_build_ids => array(select build_id from builds)\r\n\t, input_coverage_branches => array[{{branch}}]::varchar[]\r\n\t, input_baseline_build_id => {{baseline}}\r\n\t[[, input_coverage_app_env_ids => array[{{app_env}}]::varchar[] ]]\r\n\t[[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n) c\r\nJOIN builds b ON b.group_id = c.group_id AND b.app_id = c.app_id AND b.build_id = c.build_id\r\nORDER BY b.committed_at ASC, b.created_at ASC"}}', '{"graph.show_goal":false,"graph.show_values":false,"graph.series_order_dimension":null,"graph.x_axis.title_text":"Builds","graph.y_axis.scale":"linear","graph.y_axis.auto_split":false,"graph.metrics":["Total Probes","Covered","Covered in other builds"],"graph.y_axis.axis_enabled":true,"graph.series_order":null,"series_settings":{"Covered":{"color":"#227FD2"},"Total Probes":{"color":"#E75454"},"Aggregated Coverage":{"title":"Covered in other builds","color":"#87BCEC","display":"area"},"Isolated Covererage":{"color":"#227FD2","title":"Covered","display":"area"},"Covered in other builds":{"color":"#87BCEC"}},"graph.y_axis.auto_range":true,"graph.dimensions":["Version"]}', 1, 2, NULL, 'native', false, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"Build ID","field_ref":["field","Build ID",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"Build ID","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Text":{"percent-json":null,"percent-url":null,"percent-email":null,"percent-state":null,"average-length":null}}}},{"display_name":"Version","field_ref":["field","Version",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"Version","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Text":{"percent-json":null,"percent-url":null,"percent-email":null,"percent-state":null,"average-length":n