INSERT INTO public.report_card VALUES (71, '2025-02-20 11:18:57.383049+01', '2025-11-11 18:14:19.286277+01', 'Coverage by Builds', NULL, 'area', '{"database":2,"type":"native","native":{"template-tags":{"group":{"type":"text","name":"group","id":"81076167-a254-43dc-9af2-ecd5c49fad98","display-name":"Group"},"app":{"type":"text","name":"app","id":"10a03d4f-e7d5-461c-95ba-45a876891839","display-name":"App"},"branch":{"type":"text","name":"branch","id":"93154ae5-e355-49c0-8de7-08134d4c1a01","display-name":"Branch"},"baseline":{"type":"text","name":"baseline","id":"ea8d904b-fa79-4fa9-ad58-2e986730e306","display-name":"Baseline"},"test_tag":{"type":"text","name":"test_tag","id":"baca31f5-5156-44ca-a312-203d1a6bc70b","display-name":"Test Tag"},"app_env":{"type":"text","name":"app_env","id":"edeb3675-3ee3-412c-80c0-3a93a5bb7fde","display-name":"App Env"},"limit":{"type":"number","name":"limit","id":"2ee73281-8641-4b47-a6c9-41d1dd79e070","display-name":"Limit","default":"100","widget-type":null,"required":true}},"query":"WITH\r\nbuilds AS (\r\n    SELECT\r\n    \tb.group_id,\r\n    \tb.app_id,\r\n    \tb.build_id,\r\n    \tCASE \r\n    \t    WHEN b.build_version IS NOT NULL THEN b.build_version\r\n    \t    ELSE LEFT(b.version_id, 7)\r\n    \tEND AS version_id,\r\n    \tb.committed_at,\r\n    \tb.created_at\r\n    FROM metrics.builds b\r\n    WHERE b.group_id = {{group}}\r\n        AND b.app_id = {{app}}\r\n        AND b.branch LIKE {{branch}}\r\n        [[ AND {{app_env}} = ANY(b.app_env_ids) ]]\r\n    ORDER BY b.created_at DESC\r\n    LIMIT {{limit}}\r\n)\r\nSELECT \r\n  b.build_id AS \"Build ID\",\r\n  b.version_id AS \"Version\",\r\n  c.isolated_probes_coverage_ratio AS \"Isolated Coverage\",\r\n  c.aggregated_probes_coverage_ratio AS \"Aggregated Coverage\"\r\nFROM metrics.get_builds_with_coverage(\r\n\tinput_build_ids => array(select build_id from builds),\r\n\tinput_coverage_branches => array[{{branch}}]::varchar[]  \r\n\t[[, input_baseline_build_id => {{baseline}} ]]\r\n\t[[, input_coverage_app_env_ids => array[{{app_env}}]::varchar[] ]]\r\n\t[[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n) c\r\nJOIN builds b ON b.group_id = c.group_id AND b.app_id = c.app_id AND b.build_id = c.build_id\r\nORDER BY b.committed_at ASC, b.created_at ASC"}}', '{"graph.show_goal":true,"graph.show_values":false,"graph.x_axis.labels_enabled":true,"graph.goal_label":"100%","graph.series_order_dimension":null,"graph.x_axis.axis_enabled":"compact","graph.x_axis.title_text":"Builds","graph.y_axis.labels_enabled":false,"graph.goal_value":1,"graph.y_axis.scale":"linear","graph.y_axis.auto_split":false,"graph.label_value_frequency":"all","graph.metrics":["Isolated Coverage","Aggregated Coverage"],"graph.y_axis.axis_enabled":true,"graph.tooltip_columns":["[\"name\",\"Build ID\"]"],"graph.label_value_formatting":"auto","graph.series_order":null,"column_settings":{"[\"name\",\"Isolated Coverage\"]":{"number_style":"percent","number_separators":".,"},"[\"name\",\"Aggregated Coverage\"]":{"number_style":"percent"}},"series_settings":{"Isolated Coverage":{"title":"Covered","color":"#227FD2"},"Aggregated Coverage":{"title":"Covered in other builds","color":"#87BCEC","display":"area"}},"graph.y_axis.auto_range":true,"graph.dimensions":["Version"],"stackable.stack_type":null}', 1, 2, NULL, 'native', false, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"Build ID","field_ref":["field","Build ID",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"Build ID","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Text":{"percent-json":null,"percent-url":null,"percent-email":null,"percent-state":null,"average-length":null}}}},{"display_name":"Version","field_ref":["field","Version",{"base-type":"type/Text"}],"base_type":"type/Text","effective_type":"type/Text","name":"Version","semantic_type":null,"fingerprint":{"global":{"distinct-count":0,"nil%":null},"type":{"type/Text