INSERT INTO public.report_card VALUES (173, '2025-11-11 17:57:05.723831+01', '2025-11-11 17:57:39.450298+01', 'Test Definition - Package Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"28c8e3af-50db-4e01-84ba-2ebd1ea897a2","display-name":"Build"},"test_session":{"type":"text","name":"test_session","id":"4ca27147-c562-4ea7-a564-9802ee2d0a88","display-name":"Test Session"},"app_env":{"type":"text","name":"app_env","id":"e53e3d37-a0cf-4447-9832-6c0d30c50a41","display-name":"App Env"},"test_definition":{"type":"text","name":"test_definition","id":"faf713f0-47d9-49cc-8e06-e28c1e2daaf3","display-name":"Test Definition"}},"query":"WITH\nMethodsCoverage AS (\n\tSELECT\n\t\tREVERSE(\n\t\t\tSUBSTRING(\n\t\t\t\tREVERSE(class_name) FROM POSITION(''/'' IN REVERSE(class_name)) + 1)) AS package_name,\n\t\t*\n\tFROM metrics.get_methods_with_coverage_by_test_definition(\n\t    input_build_id => {{build}},\n\t    input_test_session_id => {{test_session}},\n\t    input_test_definition_id => {{test_definition}}\n\t    [[, input_coverage_app_env_ids => array[{{app_env}}]::varchar[] ]]\n\t)\n)\nSELECT\n\tpackage_name,\n\tSUM(probes_count) as probes_count,\n\tSUM(covered_probes) as covered_probes,\n\tSUM(missed_probes) as missed_probes,\n\tCAST(SUM(covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio\nFROM MethodsCoverage\nGROUP BY package_name\nORDER BY\n    missed_probes DESC"}}', '{"graph.show_goal":false,"graph.show_values":false,"scatter.bubble":"probes_count","table.columns":[{"name":"package_name","fieldRef":["field","package_name",{"base-type":"type/Text"}],"enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"covered_probes","enabled":true},{"name":"missed_probes","fieldRef":["field","missed_probes",{"base-type":"type/BigInteger"}],"enabled":true},{"name":"probes_coverage_ratio","fieldRef":["