INSERT INTO public.report_card VALUES (68, '2025-02-19 10:19:52.296745+01', '2025-10-24 16:14:48.236041+02', 'Table - Recommended Tests', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"ba0e5901-41ee-4faa-bc2b-1553609ccf09","display-name":"Build"},"env":{"type":"text","name":"env","id":"d5cbeb15-f5fa-4477-aa7f-d41286de4cd0","display-name":"Env"},"test_tag":{"type":"text","name":"test_tag","id":"00b70994-3982-492a-8314-e93eb1b4b1c6","display-name":"Test Tag"},"impact_status":{"type":"text","name":"impact_status","id":"c94a11ba-bb54-49ef-8a8d-a687dde16034","display-name":"Impact Status"},"branch":{"type":"text","name":"branch","id":"6d2958e6-b1a1-4584-9941-248bcbc1b514","display-name":"Branch"},"baseline":{"type":"text","name":"baseline","id":"1fcf2e1b-1c77-4082-82e5-d73cb21eaca6","display-name":"Baseline"}},"query":"SELECT DISTINCT\r\n  td.test_path,\r\n  td.test_name,\r\n  td.test_duration_avg,\r\n  metrics.format_duration_rounded(td.test_duration_avg::bigint) AS test_duration_avg_formatted,\r\n  td.test_runner,\r\n  td.test_tags,\r\n  array_to_string(td.test_tags, '', '') AS test_tags_formatted,\r\n  rt.test_impact_status,\r\n  rt.impacted_methods\r\nFROM metrics.get_recommended_tests_v2(\r\n\t\tinput_build_id => {{build}},\r\n\t\tinput_test_impact_statuses => ARRAY[''IMPACTED'', ''NOT_IMPACTED'']\r\n\t\t[[, input_test_impact_statuses => ARRAY[{{impact_status}}]::varchar[] ]]\r\n\t\t[[, input_baseline_until_build_id => {{baseline}} ]]\r\n\t\t[[, input_baseline_build_branches => array[{{branch}}]::varchar[] ]]\r\n\t\t[[, input_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n\t\t[[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n\t) rt\r\nJOIN metrics.test_definitions_with_statistics td ON td.group_id = rt.group_id AND td.test_definition_id = rt.test_definition_id\r\n"}}', '{"table.columns":[{"name":"test_path","enabled":true},{"name":"test_name","enabled":true},{"name":"test_durati