INSERT INTO public.report_card VALUES (174, '2025-11-11 17:58:03.175777+01', '2025-11-11 17:58:37.224762+01', 'Test Definition - Methods Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"5da451ad-e743-4b63-a2f1-757dfe5b1d92","display-name":"Build"},"class":{"type":"text","name":"class","id":"1218fecd-3609-45ea-bc3d-b2c3f96bfc5d","display-name":"Class"},"test_session":{"type":"text","name":"test_session","id":"df86c571-e933-40e9-a649-85191fa5b48d","display-name":"Test Session"},"app_env":{"type":"text","name":"app_env","id":"2ae4fcd4-a045-4457-b2e2-80aed49bbd33","display-name":"App Env"},"test_definition":{"type":"text","name":"test_definition","id":"ed8fb683-3208-43b1-98e0-572c30087aad","display-name":"Test Definition"}},"query":"WITH\nMethodsCoverage AS (\n   SELECT\n        REVERSE(\n\t\t\tSUBSTRING(\n\t\t\t\tREVERSE(class_name) FROM POSITION(''/'' IN REVERSE(class_name)) + 1)) AS package_name,\n        *\n    FROM metrics.get_methods_with_coverage_by_test_definition(\n\t    input_build_id => {{build}},\n\t\tinput_test_session_id => {{test_session}},\n\t\tinput_test_definition_id => {{test_definition}},\n\t\tinput_signature_pattern => {{class}}||''%''\n\t    [[, input_coverage_app_env_ids => array[{{app_env}}]::varchar[] ]]\n    )\n)\nSELECT \n  package_name,\n  class_name,\n  method_name,\n  method_params,\n  return_type,\n  SUM(probes_count) as probes_count,\n  SUM(covered_probes) as covered_probes,\n  SUM(missed_probes) as missed_probes,\n  CAST(SUM(covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio\nFROM\n    MethodsCoverage\nGROUP BY package_name, class_name, method_name, method_params, return_type\nORDER BY\n    missed_probes DESC"}}', '{"table.columns":[{"name":"package_name","enabled":false},{"name":"class_name","enabled":true},{"name":"method_name","enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/Inte