INSERT INTO public.report_card VALUES (159, '2025-06-30 12:47:43.298316+02', '2025-06-30 14:24:57.627551+02', 'Build Coverage', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"class_name":{"type":"text","name":"class_name","id":"a8dca109-6e26-4988-b2bc-19b3a937fbf8","display-name":"Class Name"},"branch":{"type":"text","name":"branch","id":"ff3203e5-43eb-4a77-a0b2-589f4ca8e94c","display-name":"Branch"},"test_session":{"type":"text","name":"test_session","id":"daa308f4-2566-49b6-a3ca-2ac9c7881c8f","display-name":"Test Session"},"package_name":{"type":"text","name":"package_name","id":"0d9a48e0-fbb9-4c76-a2bd-632dd8d168f9","display-name":"Package Name"},"test_tag":{"type":"text","name":"test_tag","id":"951fe343-1f5a-4313-a19e-a02f13f0fbb8","display-name":"Test Tag"},"build":{"type":"text","name":"build","id":"5942ceb7-c363-48b1-bdd3-389841865da3","display-name":"Build"},"baseline":{"type":"text","name":"baseline","id":"bfbbbc54-e916-4891-963d-48aa0783284b","display-name":"Baseline"},"test_launch":{"type":"text","name":"test_launch","id":"7d225b20-ce90-4058-9cab-20aa652e01a5","display-name":"Test Launch"},"env":{"type":"text","name":"env","id":"d6862b30-fb32-40ed-a49e-9b8f2674c6e2","display-name":"Env"}},"query":"SELECT \r\n    v.probes, \r\n    v.methods, \r\n    v.metric\r\nFROM metrics.get_builds_with_coverage(\r\n    input_build_id => {{build}}\r\n    [[, input_test_session_id => {{test_session}}]]\r\n    [[, input_test_launch_id => {{test_launch}}]]\r\n    [[, input_baseline_build_id => {{baseline}}]]\r\n    [[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n    [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n    [[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\r\n\t[[, input_package_name_pattern => {{package_name}} || ''%'']]\r\n\t[[, input_class_name_pattern => {{class_name}}]]\r\n) c\r\nCROSS JOIN LATERAL UNNEST(\r\n\tARRAY[c.isolated_covered_probes, c.aggregated_covered_probes - c.isolated_covered_probes, c.total_probes - c.aggregated_covered_probes, c.total_probes - c.isolated_covered_probes],\r\n\tARRAY[c.isolated_tested_methods, c.aggregated_tested_methods - c.isolated_tested_methods, c.total_methods - c.aggregated_tested_methods, c.total_methods - c.isolated_tested_methods],\r\n\tARRAY[''Covered'', ''Covered in other builds'', ''Gaps'', ''Gaps in current build'']  \r\n) AS v(probes, methods, metric)"}}', '{"pie.metric":"probes","pie.dimension":["metric"],"pie.rows":[{"key":"Covered","name":"Covered","originalName":"Covered","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Covered in other builds","name":"Covered in other builds","originalName":"Covered in other builds","color":"#87BCEC","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Gaps","name":"Gaps","originalName":"Gaps","color":"#ED8535","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Gaps in current build","name":"Gaps in current build","originalName":"Gaps in current build","color":"#F7CBA9","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Isolated","name":"Isolated","originalName":"Isolated","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":true,"isOther":false},{"key":"Aggregated","name":"Aggregated","originalName":"Aggregated","color":"#87BCEC","defaultColor":false,"enabled":true,"hidden":true,"isOther":false}],"pie.sort_rows":false}', 1, 2, NULL, 'native', false, 3, NULL, NULL, false, NULL, NULL, '[{"display_name":"probes","field_ref":["field","probes",{"base-type":"type/Integer"}],"base_type":"type/Integer","effective_type":"type/Integer","name":"probes","semantic_type":null,"fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Number":{"min":31306.0,"q1":94131.5,"q3":378549.0,"max":394202.0,"sd":172508.39015803454,"avg":236340.25}}}},{"display_name":"methods","field_ref":["field","methods",{"base-type":"type/Integer"}],"base_typ