INSERT INTO public.report_card VALUES (177, '2025-11-12 15:58:09.859669+01', '2025-11-12 15:58:09.859669+01', 'Impacted Methods - Table', 'Returns list of impacted methods based on difference between given Target build and Baseline build', 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"376d81c1-bea7-4abb-a3a1-2c66b76b5b32","display-name":"Build"},"baseline":{"type":"text","name":"baseline","id":"036ba902-338f-4b4d-8d41-6e2979225f50","display-name":"Baseline"},"test_tag":{"type":"text","name":"test_tag","id":"8fe87c6f-a622-4114-94ed-dacdbd124dc1","display-name":"Test Tag"},"branch":{"type":"text","name":"branch","id":"25b8e8c8-670d-4fe4-9f6d-c2647785ebda","display-name":"Branch"},"impacted_method_signature":{"type":"text","name":"impacted_method_signature","id":"3aa00880-ba3e-46ce-97bd-42044c072a64","display-name":"Impacted Method Signature"},"env":{"type":"text","name":"env","id":"a1035723-64c6-4d5d-bd0e-8d6a86bbb848","display-name":"Env"}},"query":"select \r\n    group_id,\r\n    test_definition_id,\r\n    test_path,\r\n    test_name,\r\n    test_tags,\r\n    test_metadata,\r\n    test_runner,\r\n    impacted_methods\r\nfrom metrics.get_impacted_tests_v2(\r\n    input_build_id => {{build}},\r\n    input_baseline_build_id => {{baseline}},\r\n    input_method_signature_pattern => {{impacted_method_signature}}\r\n    [[, input_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n    [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n    [[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\r\n)\r\norder by test_path asc"}}', '{"table.columns":[{"name":"group_id","enabled":false},{"name":"test_definition_id","enabled":false},{"name":"test_path","enabled":true},{"name":"test_name","enabled":true},{"name":"test_tags","enabled":true},{"name":"test_metadata","enabled":true},{"name":"impacted_methods","enabled":false}],"table.pivot_column":"group_id","table.cell_column":"impacted_methods","