INSERT INTO public.report_card VALUES (7, '2024-06-21 14:26:36.275785+02', '2025-07-16 07:52:13.775204+02', 'Methods Coverage', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"5da451ad-e743-4b63-a2f1-757dfe5b1d92","display-name":"Build"},"env_id":{"type":"text","name":"env_id","id":"2ae4fcd4-a045-4457-b2e2-80aed49bbd33","display-name":"Env ID"},"branch":{"type":"text","name":"branch","id":"768661b3-c83e-4a13-ba53-a1c7756364f9","display-name":"Branch"},"tags":{"type":"text","name":"tags","id":"44b66e43-d0d4-4f9b-91f5-0797e6e73a59","display-name":"Tags"},"class":{"type":"text","name":"class","id":"1218fecd-3609-45ea-bc3d-b2c3f96bfc5d","display-name":"Class"},"test_launch":{"type":"text","name":"test_launch","id":"fe8ec568-a273-4e34-9ab6-6887126e3837","display-name":"Test Launch"},"test_session":{"type":"text","name":"test_session","id":"50d3c7a2-f7d8-4ffd-8ae5-70eaab281dbc","display-name":"Test Session"}},"query":"WITH\nMethodsCoverage AS (\n   SELECT\n        REVERSE(\n\t\t\tSUBSTRING(\n\t\t\t\tREVERSE(class_name) FROM POSITION(''/'' IN REVERSE(class_name)) + 1)) AS package_name,\n        *\n    FROM metrics.get_methods_with_coverage(\n\t    input_build_id => {{build}},\n\t\tinput_class_name_pattern => {{class}}\n\t\t[[, input_test_session_id => {{test_session}}]]\n\t\t[[, input_test_launch_id => {{test_launch}} ]]\n\t    [[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\n\t    [[, input_coverage_app_env_ids => array[{{env_id}}]::varchar[] ]]\n        [[, input_coverage_test_tags => array[{{tags}}]::varchar[] ]]\n    )\n)\nSELECT \n  package_name,\n  class_name,\n  method_name,\n  method_params,\n  return_type,\n  SUM(probes_count) as probes_count,\n  SUM(isolated_covered_probes) as isolated_covered_probes,\n  SUM(isolated_missed_probes) as isolated_missed_probes,\n  CAST(SUM(isolated_covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS isolated_probes_coverage_ratio,\n  SUM(aggregated_covered_probes) as covered_probes,\n  SUM(aggregated_missed_probes) as missed_probes,\n  CAST(SUM(aggregated_covered_probes) AS FLOAT) / CAST(SUM(probes_count) AS FLOAT) AS probes_coverage_ratio\nFROM\n    MethodsCoverage\nGROUP BY package_name, class_name, method_name, method_params, return_type\nORDER BY\n    missed_probes DESC"}}', '{"table.columns":[{"name":"package_name","enabled":false},{"name":"class_name","enabled":true},{"name":"method_name","enabled":true},{"name":"probes_count","fieldRef":["field","probes_count",{"base-type":"type/Integer"}],"enabled":true},{"name":"covered_probes","enabled":true},{"name":"missed_probes","fieldRef":["field","missed_probes",{"base-type":"type/Integer"}],"enabled":true},{"name":"probes_coverage_ratio","fieldRef":["field","probes_coverage_ratio",{"base-type":"type/Float"}],"enabled":true},{"name":"method_params","enabled":true},{"name":"return_type","fieldRef":["field","return_type",{"base-type":"type/Text"}],"enabled":true},{"name":"isolated_covered_probes","enabled":true},{"name":"isolated_missed_probes","enabled":true},{"name":"isolated_probes_coverage_ratio","enabled":true}],"table.pivot_column":"__build_id","table.cell_column":"__probes_count","table.column_formatting":[{"columns":["isolated_probes_coverage_ratio"],"type":"range","colors":["hsla(358, 71%, 62%, 1)","#F9CF48","#84BB4C"],"min_type":"custom","max_type":"custom","min_value":0,"max_value":1},{"max_value":1,"color":"#509EE3","columns":["__probes_coverage_ratio","probes_coverage_ratio"],"value":"","type":"range","colors":["#ED6E6E","#F9CF48","#84BB4C"],"highlight_row":false,"min_value":0,"min_type":"custom","operator":"=","max_type":"custom"},{"max_value":100,"color":"#EF8C8C","columns":["__covered_probes","probes_coverage_ratio"],"value":0,"type":"single","colors":["#ED6E6E","#FFFFFF","#84BB4C"],"highlight_row":true,"min_value":0,"min_type":null,"operator":"=","max_type":null}],"column_settings":{"[\"name\",\"method_params\"]":{"column_title":"Param