INSERT INTO public.report_card VALUES (69, '2025-02-19 14:41:40.111416+01', '2025-10-23 14:47:22.66356+02', 'Tests To Skip', NULL, 'scalar', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"2ccf165e-ad75-4f06-83c9-3a24de8c37c0","display-name":"Build"},"branch":{"type":"text","name":"branch","id":"760af9c4-b171-42e1-ae6e-6e5f7fdd562b","display-name":"Branch"},"env":{"type":"text","name":"env","id":"69510365-98e1-4289-86d7-536333802830","display-name":"Env"},"test_tag":{"type":"text","name":"test_tag","id":"e2e2df0f-0fbc-4ea0-9313-9f3ae657dfac","display-name":"Test Tag"},"baseline_build":{"type":"text","name":"baseline_build","id":"8d9553ce-d6f8-448c-93eb-8d0f618b45eb","display-name":"Baseline Build"}},"query":"SELECT\n    COUNT(*) AS recommended_tests\nFROM\n  metrics.get_recommended_tests_v2 (\n    input_build_id => {{build}},\n    input_test_impact_statuses => ''{NOT_IMPACTED}''\n    [[, input_baseline_until_build_id => {{baseline_build}} ]] \n    [[, input_baseline_build_branches => array[{{branch}}]::varchar[] ]] \n    [[, input_test_tags => array[{{test_tag}}]::varchar[] ]] \n    [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\n  )  "}}', '{}', 1, 2, NULL, 'native', false, 9, NULL, NULL, false, NULL, NULL, '[{"display_name":"recommended_tests","field_ref":["field","recommended_tests",{"base-type":"type/BigInteger"}],"base_type":"type/BigInteger","effective_type":"type/BigInteger","name":"recommended_tests","semantic_type":null,"fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Number":{"min":39.0,"q1":39.0,"q3":39.0,"max":39.0,"sd":null,"avg":39.0}}}}]', NULL, 'mRJNdV-GcPzHKqJhzI37q', '[{"id":"2ccf165e-ad75-4f06-83c9-3a24de8c37c0","type":"category","target":["variable",["template-tag","build"]],"name":"Build","slug":"build"},{"id":"760af9c4-b171-42e1-ae6e-6e5f7fdd562b","type":"category","target":["variable",["template-tag","branch"]],"name":"Branch","slug":"branch"},{"id":"695