INSERT INTO public.report_card VALUES (2, '2024-06-06 19:36:51.835891+02', '2025-10-27 16:48:15.993951+01', 'Risks Report', 'List of changes between two Builds of Application Under Test.
Build - "current" build you want metrics for.
Baseline Build - a build to compare with.', 'table', '{"database":2,"type":"native","native":{"template-tags":{"build":{"type":"text","name":"build","id":"b0fa82b0-2234-4e10-bdde-fde786222085","display-name":"Build","required":true},"branch":{"type":"text","name":"branch","id":"09419f1a-3739-4d75-bd65-ff3fe129a916","display-name":"Branch"},"baseline":{"type":"text","name":"baseline","id":"cf321815-e651-4789-aa14-01387c9174fa","display-name":"Baseline"},"test_tag":{"type":"text","name":"test_tag","id":"d91b39e7-f1cf-4b2f-9a3d-0c1fa5af66cd","display-name":"Test Tag"},"env":{"type":"text","name":"env","id":"b476b9d2-845f-4194-bc30-0d6833577524","display-name":"Env"}},"query":"SELECT\r\n    c.change_type,\r\n    c.class_name,\r\n    c.method_name,\r\n    c.method_params,\r\n    c.return_type,\r\n    c.probes_count,\r\n    c.isolated_covered_probes,\r\n    c.isolated_missed_probes,\r\n    c.isolated_probes_coverage_ratio,\r\n    c.aggregated_covered_probes,\r\n    c.aggregated_missed_probes,\r\n    c.aggregated_probes_coverage_ratio,\r\n    c.signature,\r\n    COALESCE(i.impacted_tests, 0) as impacted_tests\r\nFROM metrics.get_changes_with_coverage(\r\n        input_build_id => {{build}},\r\n        input_baseline_build_id => {{baseline}}\r\n        [[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n        [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n        [[, input_coverage_branches => array[{{branch}}]::varchar[] ]]\r\n    ) c\r\nLEFT JOIN metrics.get_impacted_methods_v2(\r\n    input_build_id => {{build}},\r\n    input_baseline_build_id => {{baseline}}\r\n    [[, input_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n) i\r\nON c.signature = i.signature\r\nORDER BY aggregated_missed_probes DESC"}}', '{"table.columns":[{"name":"change_type","fieldRef":["field","change_type",{"base-type":"type/Text"}],"enabled":true},{"name":"impacted_tests","enabled":true},{"name":"class_name","enabled":true},{"name":"method_name","enabled":tru