INSERT INTO public.report_card VALUES (167, '2025-11-11 17:16:50.54429+01', '2025-11-11 17:32:33.26833+01', 'Test Session - Coverage', NULL, 'pie', '{"database":2,"type":"native","native":{"template-tags":{"class_name":{"type":"text","name":"class_name","id":"a8dca109-6e26-4988-b2bc-19b3a937fbf8","display-name":"Class Name"},"test_session":{"type":"text","name":"test_session","id":"daa308f4-2566-49b6-a3ca-2ac9c7881c8f","display-name":"Test Session"},"package_name":{"type":"text","name":"package_name","id":"0d9a48e0-fbb9-4c76-a2bd-632dd8d168f9","display-name":"Package Name"},"test_tag":{"type":"text","name":"test_tag","id":"951fe343-1f5a-4313-a19e-a02f13f0fbb8","display-name":"Test Tag"},"build":{"type":"text","name":"build","id":"5942ceb7-c363-48b1-bdd3-389841865da3","display-name":"Build"},"env":{"type":"text","name":"env","id":"d6862b30-fb32-40ed-a49e-9b8f2674c6e2","display-name":"Env"}},"query":"SELECT \r\n    v.probes, \r\n    v.methods, \r\n    v.metric\r\nFROM metrics.get_builds_with_coverage_by_test_session(\r\n    input_build_id => {{build}},\r\n    input_test_session_id => {{test_session}}\r\n    [[, input_coverage_test_tags => array[{{test_tag}}]::varchar[] ]]\r\n    [[, input_coverage_app_env_ids => array[{{env}}]::varchar[] ]]\r\n\t[[, input_package_name_pattern => {{package_name}} || ''%'']]\r\n\t[[, input_signature_pattern => {{class_name}} || ''%'']]\r\n) c\r\nCROSS JOIN LATERAL UNNEST(\r\n\tARRAY[c.covered_probes, c.total_probes - c.covered_probes],\r\n\tARRAY[c.tested_methods, c.total_methods - c.tested_methods],\r\n\tARRAY[''Covered'', ''Gaps'']  \r\n) AS v(probes, methods, metric)"}}', '{"pie.metric":"probes","pie.dimension":["metric"],"pie.rows":[{"key":"Covered","name":"Covered","originalName":"Covered","color":"#227FD2","defaultColor":false,"enabled":true,"hidden":false,"isOther":false},{"key":"Covered in other builds","name":"Covered in other builds","originalName":"Covered in other builds","color":"#87BCEC","defaultColor":false,"enabled":true