INSERT INTO public.setting VALUES ('version-info', '{"latest":{"version":"v0.52.5","released":"2025-01-08","patch":true,"highlights":["Make JWT Identity Provider URI Setting optional","docs - note on bigquery structs","docs - links","Update Loki snapshots for 2025 in release-x.52.x branch","docs - separate google sign-in and ldap docs","dopcs - add link to support matrix","docs: fix alert links","Cache logins in e2e tests","Docs still reference bell icon","[svg] Limit the lifetime of a cached Truffle JS object to sidestep apparent memory leaks","put field usage behind a feature flag and turn it off by default","Handle exception in rollback better","Ensure collections'' effective_location is batch hydrated when hydrating effective_parent","docs - env vars in config files","split up query stage e2e test file","Small a11y improvements","Fix instance stats cypress test + ensure it runs in CI","Enable N-parallelism for e2e tests","Graph lines are disappear after mouse over","Convert ChartSettingFieldsPartition to mantine","Sending a notifications test should show the response if it is a non 200 reponse","perf: Make registered? and initialized? checks faster for already initialized drivers","Grid color in the EditableDashboard component should be themeable in the sdk","Document MB_DISABLE_SCHEDULER?","Move CONTRIBUTING.md to standard location (root)"],"rollout":100},"older":[{"version":"v0.51.11.3","released":"2025-01-14","patch":true,"highlights":[]},{"version":"v0.52.5.5","released":"2025-01-14","patch":true,"highlights":[]},{"version":"v0.52.5.4","released":"2025-01-13","patch":true,"highlights":[]},{"version":"v0.52.5.3","released":"2025-01-11","patch":true,"highlights":[]},{"version":"v0.51.11.2","released":"2025-01-11","patch":true,"highlights":[]},{"version":"v0.52.5.2","released":"2025-01-10","patch":true,"highlights":[]},{"version":"v0.51.11.1","released":"2025-01-09","patch":true,"highlights":[]},{"version":"v0.51.11","released":"2025-01-08","patch":true,"highli